"""More project templates, registered into arch_templates.TEMPLATES on import (`import arch_templates_more`).

Same rules as arch_templates.py: each template is a small, working, tested project as plain data (README with how to
run it, pyproject.toml, a package, tests/), standard library only, no network. Placeholders: __NAME__ (display
name) and __PKG__ (python identifier, also used in paths). Every test file puts the project root on sys.path.

    cli_tool  tui_app  etl_pipeline  state_machine  event_bus  cache_layer  plugin_host  docs_site
"""
from arch_templates import _t, COMMON, KEYWORDS

# ------------------------------------------------------------------------------------------------ cli_tool
_t('cli_tool', 'Command-line tool (subcommands, --json, exit codes)',
   'A real CLI on argparse: add/list/done/rm subcommands over a JSON store, --json output for scripts, documented exit codes (0 ok, 1 not found, 2 usage, 3 bad data), and tests that run the CLI in-process.',
   'python / argparse', ['api'], {
       **COMMON,
       'README.md': '# __NAME__\n\nA real command-line tool: a task list kept in one JSON file, with argparse subcommands, `--json` output for\nscripts, and exit codes you can test in a shell.\n\n    python -m __PKG__ add Buy milk\n    python -m __PKG__ list\n    python -m __PKG__ done 1\n    python -m __PKG__ list --all --json\n    python -m __PKG__ rm 1\n    python -m pytest -q\n\nThe store is `tasks.json` in the current folder; change it with `--store PATH` or the `TASKS_STORE` variable.\n\n## Exit codes\n\n| code | meaning |\n|------|---------|\n| 0 | done |\n| 1 | no task with that id |\n| 2 | bad usage (unknown command, missing argument, empty title) |\n| 3 | the store file is unreadable or not a task list |\n\nWith `--json`, success prints the result as JSON on stdout and a failure prints `{"error": ..., "code": ...}`.\n',
       'pyproject.toml': '[project]\nname = "__PKG__"\nversion = "0.1.0"\nrequires-python = ">=3.10"\n\n[tool.pytest.ini_options]\ntestpaths = ["tests"]\n',
       '__PKG__/__init__.py': '"""__NAME__: a task list on the command line."""\n\n__version__ = "0.1.0"\n',
       '__PKG__/__main__.py': 'import sys\n\nfrom .cli import main\n\nsys.exit(main())\n',
       '__PKG__/cli.py': '"""The command line: parse, call the store, print text or JSON, return an exit code (never sys.exit inside main)."""\nimport argparse\nimport json\nimport os\nimport sys\n\nfrom . import store\n\nEXIT_OK = 0\nEXIT_NOT_FOUND = 1\nEXIT_USAGE = 2\nEXIT_BAD_DATA = 3\n\n\ndef build_parser():\n    common = argparse.ArgumentParser(add_help=False)\n    common.add_argument("--json", action="store_true", default=argparse.SUPPRESS, help="print machine-readable JSON")\n    ap = argparse.ArgumentParser(prog="__PKG__", description="__NAME__: a task list on the command line.", parents=[common])\n    ap.add_argument("--store", default=os.environ.get("TASKS_STORE", "tasks.json"), help="the JSON file holding the tasks")\n    sub = ap.add_subparsers(dest="cmd", required=True, metavar="COMMAND")\n    p = sub.add_parser("add", help="add a task", parents=[common])\n    p.add_argument("title", nargs="+")\n    p = sub.add_parser("list", help="show open tasks", parents=[common])\n    p.add_argument("--all", action="store_true", help="include finished tasks")\n    p = sub.add_parser("done", help="mark a task finished", parents=[common])\n    p.add_argument("id", type=int)\n    p = sub.add_parser("rm", help="delete a task", parents=[common])\n    p.add_argument("id", type=int)\n    return ap\n\n\ndef _as_json(args):\n    return bool(getattr(args, "json", False))\n\n\ndef _emit(args, data, text):\n    print(json.dumps(data) if _as_json(args) else text)\n    return EXIT_OK\n\n\ndef _fail(args, code, message):\n    if _as_json(args):\n        print(json.dumps({"error": message, "code": code}))\n    else:\n        print(f"error: {message}", file=sys.stderr)\n    return code\n\n\ndef _line(t):\n    return f"[{\'x\' if t[\'done\'] else \' \'}] #{t[\'id\']} {t[\'title\']}"\n\n\ndef main(argv=None):\n    parser = build_parser()\n    try:\n        args = parser.parse_args(argv)\n    except SystemExit as e:          # argparse exits 0 for --help and 2 for bad usage; turn that into a return value\n        return EXIT_OK if e.code in (0, None) else EXIT_USAGE\n    try:\n        tasks = store.load(args.store)\n    except (OSError, ValueError) as e:\n        return _fail(args, EXIT_BAD_DATA, f"cannot read {args.store}: {e}")\n    try:\n        if args.cmd == "add":\n            tasks, task = store.add(tasks, " ".join(args.title))\n            store.save(args.store, tasks)\n            return _emit(args, task, f"added #{task[\'id\']}: {task[\'title\']}")\n        if args.cmd == "list":\n            shown = store.visible(tasks, args.all)\n            return _emit(args, shown, "\\n".join(_line(t) for t in shown) or "no tasks")\n        if args.cmd == "done":\n            tasks, task = store.mark_done(tasks, args.id)\n            store.save(args.store, tasks)\n            return _emit(args, task, f"done #{task[\'id\']}: {task[\'title\']}")\n        tasks, task = store.remove(tasks, args.id)\n        store.save(args.store, tasks)\n        return _emit(args, task, f"removed #{task[\'id\']}: {task[\'title\']}")\n    except store.NotFound as e:\n        return _fail(args, EXIT_NOT_FOUND, f"no task #{e.args[0]}")\n    except ValueError as e:\n        return _fail(args, EXIT_USAGE, str(e))\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n',
       '__PKG__/store.py': '"""The task store: pure functions over a list of task dicts, plus load/save of one JSON file.\n\nThe functions never mutate their input; each returns the new list, so the CLI saves only when a command succeeds.\n"""\nimport json\nimport os\n\n\nclass NotFound(LookupError):\n    """No task has that id."""\n\n\ndef load(path):\n    """-> list of tasks. A missing file is an empty list; a file that is not a task list raises ValueError."""\n    if not os.path.exists(path):\n        return []\n    with open(path, "r", encoding="utf-8") as f:\n        data = json.load(f)\n    if not isinstance(data, list) or not all(isinstance(t, dict) and "id" in t and "title" in t for t in data):\n        raise ValueError("not a task list")\n    return data\n\n\ndef save(path, tasks):\n    """Write atomically: a crash mid-write leaves the old file intact."""\n    folder = os.path.dirname(os.path.abspath(path))\n    os.makedirs(folder, exist_ok=True)\n    tmp = path + ".tmp"\n    with open(tmp, "w", encoding="utf-8") as f:\n        json.dump(tasks, f, indent=2)\n    os.replace(tmp, path)\n\n\ndef add(tasks, title):\n    """-> (new list, new task). Ids are never reused while a higher id exists."""\n    title = " ".join(title.split())\n    if not title:\n        raise ValueError("title must not be empty")\n    task = {"id": max((t["id"] for t in tasks), default=0) + 1, "title": title, "done": False}\n    return tasks + [task], task\n\n\ndef find(tasks, task_id):\n    for t in tasks:\n        if t["id"] == task_id:\n            return t\n    raise NotFound(task_id)\n\n\ndef mark_done(tasks, task_id):\n    """-> (new list, updated task)."""\n    target = dict(find(tasks, task_id), done=True)\n    return [target if t["id"] == task_id else t for t in tasks], target\n\n\ndef remove(tasks, task_id):\n    """-> (new list, removed task)."""\n    target = find(tasks, task_id)\n    return [t for t in tasks if t["id"] != task_id], target\n\n\ndef visible(tasks, show_all=False):\n    return list(tasks) if show_all else [t for t in tasks if not t["done"]]\n',
       'tests/test_cli.py': 'import json\nimport os\nimport sys\n\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n\nfrom __PKG__ import cli  # noqa: E402\n\n\ndef run(capsys, store_path, *args):\n    code = cli.main(["--store", str(store_path), *args])\n    out = capsys.readouterr()\n    return code, out.out, out.err\n\n\ndef test_add_list_done_flow_in_text(tmp_path, capsys):\n    db = tmp_path / "t.json"\n    assert run(capsys, db, "add", "Buy", "milk")[:2] == (0, "added #1: Buy milk\\n")\n    run(capsys, db, "add", "Call mum")\n    code, out, _ = run(capsys, db, "list")\n    assert code == 0 and out.splitlines() == ["[ ] #1 Buy milk", "[ ] #2 Call mum"]\n    assert run(capsys, db, "done", "1")[0] == 0\n    assert run(capsys, db, "list")[1].splitlines() == ["[ ] #2 Call mum"]\n    assert "[x] #1 Buy milk" in run(capsys, db, "list", "--all")[1]\n\n\ndef test_json_output_before_or_after_the_subcommand(tmp_path, capsys):\n    db = tmp_path / "t.json"\n    code, out, _ = run(capsys, db, "--json", "add", "one")\n    assert code == 0 and json.loads(out) == {"id": 1, "title": "one", "done": False}\n    code, out, _ = run(capsys, db, "list", "--json")\n    assert code == 0 and [t["title"] for t in json.loads(out)] == ["one"]\n\n\ndef test_unknown_id_exits_1_and_reports_in_json(tmp_path, capsys):\n    db = tmp_path / "t.json"\n    code, _, err = run(capsys, db, "done", "7")\n    assert code == cli.EXIT_NOT_FOUND and "no task #7" in err\n    code, out, _ = run(capsys, db, "rm", "7", "--json")\n    assert code == 1 and json.loads(out) == {"error": "no task #7", "code": 1}\n\n\ndef test_bad_usage_exits_2_and_does_not_write(tmp_path, capsys):\n    db = tmp_path / "t.json"\n    assert run(capsys, db, "frobnicate")[0] == cli.EXIT_USAGE\n    assert run(capsys, db, "done", "not-a-number")[0] == cli.EXIT_USAGE\n    assert run(capsys, db, "add", "  ")[0] == cli.EXIT_USAGE\n    assert not db.exists()\n\n\ndef test_corrupt_store_exits_3(tmp_path, capsys):\n    db = tmp_path / "t.json"\n    db.write_text("not json", encoding="utf-8")\n    code, _, err = run(capsys, db, "list")\n    assert code == cli.EXIT_BAD_DATA and "cannot read" in err\n\n\ndef test_help_exits_0(tmp_path, capsys):\n    code, out, _ = run(capsys, tmp_path / "t.json", "--help")\n    assert code == 0 and "add" in out and "list" in out\n',
       'tests/test_store.py': 'import os\nimport sys\n\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n\nimport pytest  # noqa: E402\n\nfrom __PKG__ import store  # noqa: E402\n\n\ndef test_add_assigns_increasing_ids_and_does_not_mutate():\n    empty = []\n    one, a = store.add(empty, "  write   docs ")\n    two, b = store.add(one, "ship")\n    assert empty == [] and a == {"id": 1, "title": "write docs", "done": False} and b["id"] == 2 and len(two) == 2\n\n\ndef test_empty_title_is_refused():\n    with pytest.raises(ValueError):\n        store.add([], "   ")\n\n\ndef test_done_and_remove_and_not_found():\n    tasks, _ = store.add([], "a")\n    tasks, _ = store.add(tasks, "b")\n    tasks, t = store.mark_done(tasks, 1)\n    assert t["done"] and [x["id"] for x in store.visible(tasks)] == [2] and len(store.visible(tasks, True)) == 2\n    tasks, gone = store.remove(tasks, 2)\n    assert gone["title"] == "b" and [x["id"] for x in tasks] == [1]\n    with pytest.raises(store.NotFound):\n        store.remove(tasks, 99)\n\n\ndef test_save_and_load_round_trip(tmp_path):\n    path = str(tmp_path / "sub" / "tasks.json")\n    assert store.load(path) == []\n    tasks, _ = store.add([], "persist me")\n    store.save(path, tasks)\n    assert store.load(path) == tasks and not os.path.exists(path + ".tmp")\n\n\ndef test_load_rejects_a_file_that_is_not_a_task_list(tmp_path):\n    p = tmp_path / "tasks.json"\n    p.write_text(\'{"id": 1}\', encoding="utf-8")\n    with pytest.raises(ValueError):\n        store.load(str(p))\n',
   }, 'python -m __PKG__ list --all')

# ------------------------------------------------------------------------------------------------ tui_app
_t('tui_app', 'Terminal UI (curses, tested model)',
   'A terminal picker split the testable way: a pure model (cursor, marks, filter, scrolling, the exact screen lines) that is fully tested, and a thin curses view imported lazily so the tests never need a terminal or curses (Windows: pip install windows-curses to run the UI).',
   'python / curses', ['api'], {
       **COMMON,
       'README.md': '# __NAME__\n\nA terminal UI split the testable way: `__PKG__/model.py` holds ALL the behaviour (cursor, selection, filter,\nscrolling, what each line on screen says) as plain Python, and `__PKG__/view.py` is a thin curses shell that only\nturns key presses into names and draws the lines the model produced.\n\n    python -m __PKG__ items.txt     # one item per line; with no file it shows a sample list\n    python -m pytest -q             # tests touch only the model: no terminal needed\n\nKeys: Up/Down or j/k move, Space marks, `/` filters (type, Enter to keep, Esc to clear), Enter confirms, q quits.\nThe marked items are printed when you leave with Enter.\n\ncurses ships with Python on Linux and macOS. On Windows install it first: `pip install windows-curses`\n(the tests do not need it; `view.py` imports curses only when the UI actually starts).\n',
       'pyproject.toml': '[project]\nname = "__PKG__"\nversion = "0.1.0"\nrequires-python = ">=3.10"\n\n[tool.pytest.ini_options]\ntestpaths = ["tests"]\n',
       '__PKG__/__init__.py': '"""__NAME__: a terminal picker with a pure, tested model and a thin curses view."""\n',
       '__PKG__/__main__.py': 'import sys\n\nfrom .model import PickerModel\n\nSAMPLE = ["apples", "bread", "coffee", "dates", "eggs", "flour", "grapes", "honey", "ice cream", "jam"]\n\n\ndef main(argv=None):\n    argv = sys.argv[1:] if argv is None else argv\n    if argv:\n        with open(argv[0], "r", encoding="utf-8") as f:\n            items = [line.strip() for line in f if line.strip()]\n    else:\n        items = SAMPLE\n    try:\n        from .view import run\n        model = run(PickerModel(items))\n    except ImportError:\n        print("curses is not available. On Windows: pip install windows-curses", file=sys.stderr)\n        return 1\n    if model.confirmed:\n        print("\\n".join(model.selection()))\n    return 0\n\n\nsys.exit(main())\n',
       '__PKG__/model.py': '"""The whole UI as state. No curses here: keys arrive as names ("up", "down", "space", "enter", "esc",\n"backspace", or one printable character) and the screen leaves as a list of strings, so every behaviour is\ntestable without a terminal.\n"""\n\nNORMAL = "normal"\nFILTER = "filter"\n\n\nclass PickerModel:\n    def __init__(self, items, title="Pick items"):\n        self.items = list(items)\n        self.title = title\n        self.cursor = 0          # index into visible()\n        self.top = 0             # first visible row shown (scrolling)\n        self.marked = set()      # indexes into self.items\n        self.query = ""\n        self.mode = NORMAL\n        self.running = True\n        self.confirmed = False\n\n    # ------------------------------------------------------------------ queries\n    def visible(self):\n        """-> list of (item index, text) that pass the filter, in original order."""\n        q = self.query.lower()\n        return [(i, t) for i, t in enumerate(self.items) if q in t.lower()]\n\n    def current(self):\n        rows = self.visible()\n        return rows[self.cursor] if rows else None\n\n    def selection(self):\n        return [self.items[i] for i in sorted(self.marked)]\n\n    # ------------------------------------------------------------------ input\n    def handle(self, key):\n        """Apply one key. Returns True while the app should keep running."""\n        if self.mode == FILTER:\n            self._filter_key(key)\n        elif key in ("q", "esc"):\n            self.running = False\n        elif key in ("up", "k"):\n            self.move(-1)\n        elif key in ("down", "j"):\n            self.move(1)\n        elif key == "home":\n            self.move(-len(self.items))\n        elif key == "end":\n            self.move(len(self.items))\n        elif key == "space":\n            self.toggle()\n        elif key == "/":\n            self.mode = FILTER\n        elif key == "enter":\n            self.confirmed, self.running = True, False\n        return self.running\n\n    def _filter_key(self, key):\n        if key == "enter":\n            self.mode = NORMAL\n        elif key == "esc":\n            self.mode, self.query = NORMAL, ""\n        elif key == "backspace":\n            self.query = self.query[:-1]\n        elif len(key) == 1 and key.isprintable():\n            self.query += key\n        elif key == "space":\n            self.query += " "\n        self._clamp()\n\n    def move(self, delta):\n        self.cursor += delta\n        self._clamp()\n\n    def toggle(self):\n        row = self.current()\n        if row is not None:\n            self.marked.symmetric_difference_update({row[0]})\n\n    def _clamp(self):\n        n = len(self.visible())\n        self.cursor = max(0, min(self.cursor, n - 1)) if n else 0\n\n    # ------------------------------------------------------------------ output\n    def render(self, width, height):\n        """-> exactly `height` strings, each at most `width` characters: header, rows, footer.\n        Scrolls so the cursor row is always on screen."""\n        width, height = max(width, 1), max(height, 3)\n        body = height - 2\n        rows = self.visible()\n        if self.cursor < self.top:\n            self.top = self.cursor\n        elif self.cursor >= self.top + body:\n            self.top = self.cursor - body + 1\n        self.top = max(0, min(self.top, max(len(rows) - body, 0)))\n        lines = [f"{self.title} ({len(self.marked)} marked, {len(rows)}/{len(self.items)} shown)"]\n        for pos in range(self.top, self.top + body):\n            if pos < len(rows):\n                idx, text = rows[pos]\n                pointer = ">" if pos == self.cursor else " "\n                box = "[x]" if idx in self.marked else "[ ]"\n                lines.append(f"{pointer} {box} {text}")\n            elif pos == 0:\n                lines.append("  (nothing matches)")\n            else:\n                lines.append("")\n        footer = f"/{self.query}_  Enter keep  Esc clear" if self.mode == FILTER else "j/k move  Space mark  / filter  Enter done  q quit"\n        lines.append(footer)\n        return [line[:width] for line in lines]\n',
       '__PKG__/view.py': '"""The curses shell. Deliberately thin and NOT exercised by the tests: it maps key codes to names, asks the model\nfor its lines and draws them. curses is imported inside run() so importing this module never fails on a system\nwithout it (Windows needs `pip install windows-curses`).\n"""\n\n\ndef key_name(curses, code):\n    """Translate a curses key code into the names PickerModel.handle understands."""\n    named = {curses.KEY_UP: "up", curses.KEY_DOWN: "down", curses.KEY_HOME: "home", curses.KEY_END: "end",\n             curses.KEY_BACKSPACE: "backspace", curses.KEY_ENTER: "enter", 10: "enter", 13: "enter", 27: "esc",\n             8: "backspace", 127: "backspace", 32: "space"}\n    if code in named:\n        return named[code]\n    if 0 <= code < 256 and chr(code).isprintable():\n        return chr(code)\n    return ""\n\n\ndef run(model):\n    """Run the UI until the model stops. Returns the model so the caller can read the selection."""\n    import curses\n\n    def loop(screen):\n        curses.curs_set(0)\n        screen.keypad(True)\n        while model.running:\n            height, width = screen.getmaxyx()\n            screen.erase()\n            for y, line in enumerate(model.render(width - 1, height)):\n                screen.addstr(y, 0, line, curses.A_REVERSE if line.startswith(">") else curses.A_NORMAL)\n            screen.refresh()\n            model.handle(key_name(curses, screen.getch()))\n\n    curses.wrapper(loop)\n    return model\n',
       'tests/test_model.py': 'import os\nimport sys\n\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n\nfrom __PKG__.model import FILTER, NORMAL, PickerModel  # noqa: E402\n\nITEMS = ["apple", "banana", "cherry", "date", "elderberry", "fig", "grape"]\n\n\ndef press(model, *keys):\n    for k in keys:\n        model.handle(k)\n    return model\n\n\ndef test_cursor_moves_and_clamps_at_both_ends():\n    m = PickerModel(ITEMS)\n    press(m, "up")\n    assert m.cursor == 0\n    press(m, "down", "j", "down")\n    assert m.current() == (3, "date")\n    press(m, "end", "down")\n    assert m.cursor == len(ITEMS) - 1\n    press(m, "k", "home")\n    assert m.cursor == 0\n\n\ndef test_space_marks_and_unmarks_and_enter_confirms():\n    m = press(PickerModel(ITEMS), "space", "down", "down", "space", "down", "space", "up", "space")\n    assert m.selection() == ["apple", "date"]\n    assert press(m, "enter").confirmed and not m.running\n\n\ndef test_q_quits_without_confirming():\n    m = press(PickerModel(ITEMS), "space", "q")\n    assert not m.running and not m.confirmed\n\n\ndef test_filter_narrows_keeps_cursor_in_range_and_esc_clears():\n    m = press(PickerModel(ITEMS), "end", "/", "e", "r")\n    assert m.mode == FILTER and [t for _, t in m.visible()] == ["cherry", "elderberry"]\n    assert m.cursor == 1\n    press(m, "backspace", "backspace", "x", "y", "z")\n    assert m.visible() == [] and m.current() is None and m.cursor == 0\n    press(m, "esc")\n    assert m.mode == NORMAL and m.query == "" and len(m.visible()) == len(ITEMS)\n\n\ndef test_marks_refer_to_items_not_filtered_rows():\n    m = press(PickerModel(ITEMS), "/", "g", "r", "enter", "space")\n    assert m.mode == NORMAL and m.selection() == ["grape"]\n    press(m, "/", "esc", "space")\n    assert m.selection() == ["apple", "grape"]\n\n\ndef test_keys_typed_in_filter_mode_do_not_quit_or_move():\n    m = press(PickerModel(ITEMS), "/", "q", "j")\n    assert m.running and m.query == "qj" and m.mode == FILTER\n\n\ndef test_render_has_exact_height_width_and_pointer():\n    m = press(PickerModel(ITEMS, title="Fruit"), "down", "space")\n    lines = m.render(width=20, height=5)\n    assert len(lines) == 5 and all(len(line) <= 20 for line in lines)\n    assert lines[0].startswith("Fruit (1 marked")\n    assert lines[1] == "  [ ] apple" and lines[2] == "> [x] banana"\n\n\ndef test_render_scrolls_to_keep_the_cursor_visible():\n    m = press(PickerModel(ITEMS), "end")\n    lines = m.render(width=40, height=5)\n    body = lines[1:-1]\n    assert body[-1] == "> [ ] grape" and "apple" not in " ".join(body)\n    press(m, "home")\n    assert m.render(width=40, height=5)[1] == "> [ ] apple"\n\n\ndef test_render_says_when_nothing_matches_and_shows_the_query():\n    m = press(PickerModel(ITEMS), "/", "z", "z")\n    lines = m.render(width=60, height=4)\n    assert lines[1] == "  (nothing matches)" and lines[-1].startswith("/zz_")\n',
   }, 'python -m __PKG__')

# ------------------------------------------------------------------------------------------------ etl_pipeline
_t('etl_pipeline', 'ETL pipeline (CSV -> validated -> SQLite)',
   'Extract from CSV, validate every row against a declared schema (rejected rows go to a rejects file with their line number and every reason), transform, and upsert into SQLite. Re-running the same file is safe.',
   'python / csv / sqlite', ['data'], {
       **COMMON,
       'README.md': '# __NAME__\n\nExtract -> validate -> transform -> load, each a separate function you can test on its own:\n\n1. **extract** reads a CSV file row by row (with its line number).\n2. **validate** checks every row against the declared schema in `__PKG__/schema.py`. A row that fails is not\n   dropped silently: it goes to the rejects file with its line number and the exact reason.\n3. **transform** turns a valid row into the stored shape (lower-cased email, amount in cents, month column).\n4. **load** upserts into SQLite, so re-running the same file is safe.\n\n    python -m __PKG__ sample.csv out.db rejects.csv\n    python -m pytest -q\n\nChange what "valid" means by editing `SCHEMA`; the rest follows from it.\n',
       'pyproject.toml': '[project]\nname = "__PKG__"\nversion = "0.1.0"\nrequires-python = ">=3.10"\n\n[tool.pytest.ini_options]\ntestpaths = ["tests"]\n',
       '__PKG__/__init__.py': '"""__NAME__: CSV -> validated rows -> SQLite, with every rejected row kept and explained."""\n',
       '__PKG__/__main__.py': 'import sys\n\nfrom .pipeline import SchemaError, run\n\n\ndef main(argv=None):\n    argv = sys.argv[1:] if argv is None else argv\n    if len(argv) != 3:\n        print("usage: python -m __PKG__ INPUT.csv OUTPUT.db REJECTS.csv", file=sys.stderr)\n        return 2\n    try:\n        report = run(*argv)\n    except (OSError, SchemaError) as e:\n        print(f"error: {e}", file=sys.stderr)\n        return 1\n    print(f"read {report[\'read\']}, loaded {report[\'loaded\']}, rejected {report[\'rejected\']} (see {argv[2]})")\n    return 0\n\n\nsys.exit(main())\n',
       '__PKG__/pipeline.py': '"""extract -> validate -> transform -> load. Every connection and file is closed before run() returns, so the\ndatabase and the rejects file can be moved or deleted straight away (Windows refuses to delete an open file)."""\nimport csv\nimport sqlite3\nfrom contextlib import closing\n\nfrom .schema import SCHEMA, validate\n\nDDL = """\nCREATE TABLE IF NOT EXISTS payments (\n    id INTEGER PRIMARY KEY,\n    email TEXT NOT NULL,\n    amount_cents INTEGER NOT NULL CHECK (amount_cents >= 0),\n    paid_on TEXT NOT NULL,\n    month TEXT NOT NULL,\n    country TEXT\n);\n"""\n\n\nclass SchemaError(ValueError):\n    """The CSV header does not have the columns the schema needs."""\n\n\ndef extract(path, schema=SCHEMA):\n    """-> list of (line number, row dict). Line numbers match what a text editor shows (header is line 1)."""\n    with open(path, "r", encoding="utf-8", newline="") as f:\n        reader = csv.DictReader(f)\n        header = reader.fieldnames or []\n        missing = [fld.name for fld in schema if fld.required and fld.name not in header]\n        if missing:\n            raise SchemaError(f"missing column(s): {\', \'.join(missing)}")\n        return [(reader.line_num, row) for row in reader]\n\n\ndef transform(clean):\n    """A valid row -> the stored shape."""\n    return {\n        "id": clean["id"],\n        "email": clean["email"].lower(),\n        "amount_cents": int(round(clean["amount"] * 100)),\n        "paid_on": clean["date"].isoformat(),\n        "month": clean["date"].strftime("%Y-%m"),\n        "country": clean.get("country"),\n    }\n\n\ndef load(con, records):\n    """Upsert: loading the same file twice leaves the same rows."""\n    con.executescript(DDL)\n    con.executemany("INSERT INTO payments (id, email, amount_cents, paid_on, month, country) "\n                    "VALUES (:id, :email, :amount_cents, :paid_on, :month, :country) "\n                    "ON CONFLICT(id) DO UPDATE SET email=excluded.email, amount_cents=excluded.amount_cents, "\n                    "paid_on=excluded.paid_on, month=excluded.month, country=excluded.country", records)\n    con.commit()\n\n\ndef write_rejects(path, rejects, columns):\n    with open(path, "w", encoding="utf-8", newline="") as f:\n        w = csv.writer(f)\n        w.writerow(["line", "reason"] + list(columns))\n        for line, reason, row in rejects:\n            w.writerow([line, reason] + [row.get(c, "") for c in columns])\n\n\ndef run(csv_path, db_path, rejects_path, schema=SCHEMA):\n    """-> report {"read", "loaded", "rejected"}. Duplicate ids inside one file are rejected after the first."""\n    rows = extract(csv_path, schema)\n    good, rejects, seen = [], [], set()\n    for line, row in rows:\n        clean, reasons = validate(row, schema)\n        if not reasons and clean["id"] in seen:\n            reasons = [f"id: {clean[\'id\']} already appears earlier in this file"]\n        if reasons:\n            rejects.append((line, "; ".join(reasons), row))\n            continue\n        seen.add(clean["id"])\n        good.append(transform(clean))\n    with closing(sqlite3.connect(db_path)) as con:\n        load(con, good)\n    write_rejects(rejects_path, rejects, [fld.name for fld in schema])\n    return {"read": len(rows), "loaded": len(good), "rejected": len(rejects)}\n',
       '__PKG__/schema.py': '"""The declared schema: one Field per CSV column. validate() is driven entirely by this list."""\nimport datetime\nimport re\nfrom dataclasses import dataclass\n\n\ndef parse_int(text):\n    return int(text)\n\n\ndef parse_float(text):\n    value = float(text)\n    if value != value or value in (float("inf"), float("-inf")):\n        raise ValueError("not a finite number")\n    return value\n\n\ndef parse_date(text):\n    return datetime.date.fromisoformat(text)\n\n\ndef parse_str(text):\n    return text\n\n\n@dataclass(frozen=True)\nclass Field:\n    name: str\n    parse: object = parse_str\n    required: bool = True\n    pattern: str = ""\n    minimum: float = None\n    choices: tuple = ()\n\n\nEMAIL = r"[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}"\n\nSCHEMA = [\n    Field("id", parse_int, minimum=1),\n    Field("email", pattern=EMAIL),\n    Field("amount", parse_float, minimum=0),\n    Field("date", parse_date),\n    Field("country", required=False, choices=("GB", "US", "FI", "FR", "DE")),\n]\n\n\ndef validate(row, schema=SCHEMA):\n    """-> (clean dict, list of reasons). The row is valid when the list is empty. Every problem is reported,\n    not just the first, so one look at the rejects file tells the whole story."""\n    clean, reasons = {}, []\n    for f in schema:\n        raw = (row.get(f.name) or "").strip()\n        if not raw:\n            if f.required:\n                reasons.append(f"{f.name}: required")\n            else:\n                clean[f.name] = None\n            continue\n        try:\n            value = f.parse(raw)\n        except ValueError:\n            reasons.append(f"{f.name}: cannot read {raw!r} as {f.parse.__name__.replace(\'parse_\', \'\')}")\n            continue\n        if f.pattern and not re.fullmatch(f.pattern, raw):\n            reasons.append(f"{f.name}: {raw!r} is not in the expected format")\n        elif f.minimum is not None and value < f.minimum:\n            reasons.append(f"{f.name}: {raw} is below the minimum {f.minimum:g}")\n        elif f.choices and value not in f.choices:\n            reasons.append(f"{f.name}: {raw!r} is not one of {\', \'.join(f.choices)}")\n        else:\n            clean[f.name] = value\n    return clean, reasons\n',
       'sample.csv': 'id,email,amount,date,country\n1,Ada@Example.com,19.99,2024-03-01,GB\n2,grace@example.com,5,2024-03-15,US\n3,not-an-email,10,2024-03-20,US\n4,linus@example.com,-3,2024-04-02,FI\n5,margaret@example.com,42.50,2024-02-30,US\n',
       'tests/test_pipeline.py': 'import csv\nimport os\nimport sqlite3\nimport sys\nfrom contextlib import closing\n\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n\nimport pytest  # noqa: E402\n\nfrom __PKG__ import pipeline  # noqa: E402\nfrom __PKG__.schema import validate  # noqa: E402\n\nCSV = (\n    "id,email,amount,date,country\\n"\n    "1,Ada@Example.com,19.99,2024-03-01,GB\\n"\n    "2,grace@example.com,5,2024-03-15,\\n"\n    "3,not-an-email,10,2024-03-20,US\\n"\n    "4,linus@example.com,-3,2024-04-02,FI\\n"\n    "5,margaret@example.com,42.50,2024-02-30,US\\n"\n    "x,,abc,,ZZ\\n"\n    "1,again@example.com,1,2024-05-01,US\\n"\n)\n\n\ndef write(tmp_path, text=CSV):\n    p = tmp_path / "in.csv"\n    p.write_text(text, encoding="utf-8")\n    return str(p), str(tmp_path / "out.db"), str(tmp_path / "rejects.csv")\n\n\ndef rows(db, sql):\n    with closing(sqlite3.connect(db)) as con:\n        return con.execute(sql).fetchall()\n\n\ndef rejects(path):\n    with open(path, "r", encoding="utf-8", newline="") as f:\n        return {int(r["line"]): r["reason"] for r in csv.DictReader(f)}\n\n\ndef test_good_rows_land_transformed(tmp_path):\n    src, db, rej = write(tmp_path)\n    report = pipeline.run(src, db, rej)\n    assert report == {"read": 7, "loaded": 2, "rejected": 5}\n    assert rows(db, "SELECT id, email, amount_cents, paid_on, month, country FROM payments ORDER BY id") == [\n        (1, "ada@example.com", 1999, "2024-03-01", "2024-03", "GB"),\n        (2, "grace@example.com", 500, "2024-03-15", "2024-03", None),\n    ]\n\n\ndef test_bad_rows_are_rejected_with_their_line_and_reason(tmp_path):\n    src, db, rej = write(tmp_path)\n    pipeline.run(src, db, rej)\n    r = rejects(rej)\n    assert sorted(r) == [4, 5, 6, 7, 8]\n    assert "email" in r[4] and "expected format" in r[4]\n    assert r[5] == "amount: -3 is below the minimum 0"\n    assert "date: cannot read \'2024-02-30\'" in r[6]\n    assert all(part in r[7] for part in ("id: cannot read \'x\'", "email: required", "amount: cannot read \'abc\'", "date: required", "country: \'ZZ\'"))\n    assert r[8] == "id: 1 already appears earlier in this file"\n\n\ndef test_rerun_is_idempotent_and_files_can_be_deleted(tmp_path):\n    src, db, rej = write(tmp_path)\n    pipeline.run(src, db, rej)\n    pipeline.run(src, db, rej)\n    assert rows(db, "SELECT COUNT(*) FROM payments") == [(2,)]\n    os.remove(db)\n    os.remove(rej)\n    assert not os.path.exists(db) and not os.path.exists(rej)\n\n\ndef test_missing_required_column_stops_before_loading(tmp_path):\n    src, db, rej = write(tmp_path, "id,email,date\\n1,a@b.co,2024-01-01\\n")\n    with pytest.raises(pipeline.SchemaError, match="amount"):\n        pipeline.run(src, db, rej)\n    assert not os.path.exists(db)\n\n\ndef test_validate_reports_every_problem_at_once():\n    clean, reasons = validate({"id": "0", "email": "a@b.co", "amount": "nan", "date": "2024-01-01"})\n    assert reasons == ["id: 0 is below the minimum 1", "amount: cannot read \'nan\' as float"]\n    assert clean["email"] == "a@b.co" and clean["country"] is None\n',
   }, 'python -m __PKG__ sample.csv out.db rejects.csv')

# ------------------------------------------------------------------------------------------------ state_machine
_t('state_machine', 'Declarative state machine',
   'States, events, guards and transitions as data, checked when the machine is built; illegal events and failed guards are refused with a reason and logged in the history alongside the legal ones. Ships an order-lifecycle example.',
   'python', ['api'], {
       **COMMON,
       'README.md': '# __NAME__\n\nA declarative state machine: states, events, guards and transitions are DATA (`__PKG__/orders.py` is a worked\nexample: an order that is drafted, submitted, paid, shipped and delivered, or cancelled). The engine in\n`__PKG__/machine.py` checks the spec when it is built, refuses illegal transitions with a reason, and keeps a\nhistory of every attempt, refused ones included.\n\n    python -m __PKG__        # walks the order example and prints its history\n    python -m pytest -q\n\nA transition is `{"event": ..., "source": ..., "target": ..., "guard": optional name}`. `source` may be a list\nof states. When several transitions match, the first whose guard passes wins; if none passes, the event is\nrefused and the history says which guard said no.\n',
       'pyproject.toml': '[project]\nname = "__PKG__"\nversion = "0.1.0"\nrequires-python = ">=3.10"\n\n[tool.pytest.ini_options]\ntestpaths = ["tests"]\n',
       '__PKG__/__init__.py': '"""__NAME__: a declarative state machine with guards, history and refusals."""\n',
       '__PKG__/__main__.py': 'from .machine import TransitionRefused\nfrom .orders import add_item, new_order\n\n\ndef main():\n    order = new_order(address="1 High Street")\n    add_item(order, "book", 12)\n    order.fire("submit")\n    try:\n        order.fire("pay", {"amount": 5})\n    except TransitionRefused as e:\n        print("refused:", e.reason)\n    for event, payload in (("pay", {"amount": 12}), ("ship", {}), ("deliver", {})):\n        order.fire(event, payload)\n    for h in order.history:\n        print(f"{h[\'from\']:>10} --{h[\'event\']}--> {h[\'to\']:<10} {\'ok\' if h[\'ok\'] else \'REFUSED: \' + h[\'reason\']}")\n    print("path:", " -> ".join(order.path()))\n\n\nmain()\n',
       '__PKG__/machine.py': '"""The engine. A spec is plain data:\n\n    {"states": [...], "initial": "draft", "final": [...],\n     "transitions": [{"event": "pay", "source": "submitted", "target": "paid", "guard": "has_amount"}, ...]}\n\nGuards are named functions (context, payload) -> bool, passed in separately so the spec stays serialisable.\n"""\n\n\nclass SpecError(ValueError):\n    """The spec itself is inconsistent (unknown state, unknown guard, ...)."""\n\n\nclass TransitionRefused(Exception):\n    """An event that is not allowed right now. `.reason` says why in plain words."""\n\n    def __init__(self, state, event, reason):\n        super().__init__(f"{event!r} refused in state {state!r}: {reason}")\n        self.state, self.event, self.reason = state, event, reason\n\n\nclass IllegalTransition(TransitionRefused):\n    """No transition for this event leaves the current state."""\n\n\nclass GuardRejected(TransitionRefused):\n    """A transition exists, but every guard on it said no."""\n\n\ndef _sources(t):\n    s = t["source"]\n    return list(s) if isinstance(s, (list, tuple)) else [s]\n\n\ndef check_spec(spec, guards):\n    """Raise SpecError for the mistakes that would otherwise surface only at runtime."""\n    states = spec.get("states") or []\n    if len(set(states)) != len(states) or not states:\n        raise SpecError("states must be a non-empty list of unique names")\n    known = set(states)\n    if spec.get("initial") not in known:\n        raise SpecError(f"initial state {spec.get(\'initial\')!r} is not declared")\n    for f in spec.get("final", []):\n        if f not in known:\n            raise SpecError(f"final state {f!r} is not declared")\n    for i, t in enumerate(spec.get("transitions", [])):\n        for key in ("event", "source", "target"):\n            if key not in t:\n                raise SpecError(f"transition {i} has no {key!r}")\n        for s in _sources(t) + [t["target"]]:\n            if s not in known:\n                raise SpecError(f"transition {i} ({t[\'event\']}) uses undeclared state {s!r}")\n        if t.get("guard") and t["guard"] not in guards:\n            raise SpecError(f"transition {i} ({t[\'event\']}) names unknown guard {t[\'guard\']!r}")\n        if set(_sources(t)) & set(spec.get("final", [])):\n            raise SpecError(f"transition {i} ({t[\'event\']}) leaves a final state")\n\n\nclass Machine:\n    def __init__(self, spec, guards=None, context=None):\n        self.guards = dict(guards or {})\n        check_spec(spec, self.guards)\n        self.spec = spec\n        self.state = spec["initial"]\n        self.context = context if context is not None else {}\n        self.history = []\n\n    @property\n    def done(self):\n        return self.state in self.spec.get("final", [])\n\n    def candidates(self, event, state=None):\n        state = state or self.state\n        return [t for t in self.spec.get("transitions", []) if t["event"] == event and state in _sources(t)]\n\n    def available(self):\n        """Events that have at least one transition out of the current state (guards not evaluated)."""\n        seen = []\n        for t in self.spec.get("transitions", []):\n            if self.state in _sources(t) and t["event"] not in seen:\n                seen.append(t["event"])\n        return seen\n\n    def can(self, event, payload=None):\n        return self._pick(event, payload or {})[0] is not None\n\n    def _pick(self, event, payload):\n        """-> (transition or None, reason when None)."""\n        options = self.candidates(event)\n        if not options:\n            if self.done:\n                return None, f"{self.state!r} is final"\n            return None, f"no transition for {event!r} from {self.state!r} (allowed: {\', \'.join(self.available()) or \'none\'})"\n        refused = []\n        for t in options:\n            g = t.get("guard")\n            if not g or self.guards[g](self.context, payload):\n                return t, ""\n            refused.append(g)\n        return None, "guard(s) said no: " + ", ".join(refused)\n\n    def fire(self, event, payload=None):\n        """Apply an event. -> the new state. Raises IllegalTransition / GuardRejected; either way it is logged."""\n        payload = payload or {}\n        t, reason = self._pick(event, payload)\n        entry = {"from": self.state, "event": event, "payload": dict(payload)}\n        if t is None:\n            self.history.append(dict(entry, to=self.state, ok=False, reason=reason))\n            cls = GuardRejected if self.candidates(event) else IllegalTransition\n            raise cls(self.state, event, reason)\n        self.state = t["target"]\n        self.history.append(dict(entry, to=self.state, ok=True, reason=""))\n        return self.state\n\n    def path(self):\n        """The states actually visited, in order (refusals do not move)."""\n        return [self.spec["initial"]] + [h["to"] for h in self.history if h["ok"]]\n',
       '__PKG__/orders.py': '"""A worked example: an order\'s life as data. Swap this file for your own domain."""\nfrom .machine import Machine\n\nORDER_SPEC = {\n    "states": ["draft", "submitted", "paid", "shipped", "delivered", "cancelled"],\n    "initial": "draft",\n    "final": ["delivered", "cancelled"],\n    "transitions": [\n        {"event": "add_item", "source": "draft", "target": "draft"},\n        {"event": "submit", "source": "draft", "target": "submitted", "guard": "has_items"},\n        {"event": "pay", "source": "submitted", "target": "paid", "guard": "pays_in_full"},\n        {"event": "ship", "source": "paid", "target": "shipped", "guard": "has_address"},\n        {"event": "deliver", "source": "shipped", "target": "delivered"},\n        {"event": "cancel", "source": ["draft", "submitted"], "target": "cancelled"},\n    ],\n}\n\n\ndef has_items(ctx, payload):\n    return len(ctx.get("items", [])) > 0\n\n\ndef pays_in_full(ctx, payload):\n    return payload.get("amount", 0) >= sum(price for _, price in ctx.get("items", []))\n\n\ndef has_address(ctx, payload):\n    return bool(ctx.get("address", "").strip())\n\n\nGUARDS = {"has_items": has_items, "pays_in_full": pays_in_full, "has_address": has_address}\n\n\ndef new_order(address=""):\n    return Machine(ORDER_SPEC, GUARDS, {"items": [], "address": address})\n\n\ndef add_item(order, name, price):\n    """Context changes go with the event so the history shows them."""\n    order.fire("add_item", {"name": name, "price": price})\n    order.context["items"].append((name, price))\n    return order\n',
       'tests/test_machine.py': 'import os\nimport sys\n\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n\nimport pytest  # noqa: E402\n\nfrom __PKG__.machine import GuardRejected, IllegalTransition, Machine, SpecError, TransitionRefused  # noqa: E402\nfrom __PKG__.orders import ORDER_SPEC, GUARDS, add_item, new_order  # noqa: E402\n\n\ndef test_happy_path_reaches_a_final_state():\n    o = new_order(address="1 High Street")\n    add_item(o, "book", 12)\n    add_item(o, "pen", 3)\n    for event, payload in (("submit", {}), ("pay", {"amount": 15}), ("ship", {}), ("deliver", {})):\n        o.fire(event, payload)\n    assert o.state == "delivered" and o.done\n    assert o.path() == ["draft", "draft", "draft", "submitted", "paid", "shipped", "delivered"]\n    assert all(h["ok"] for h in o.history)\n\n\ndef test_cancel_from_either_listed_source():\n    a = new_order()\n    a.fire("cancel")\n    b = new_order()\n    add_item(b, "x", 1)\n    b.fire("submit")\n    b.fire("cancel")\n    assert a.state == b.state == "cancelled"\n\n\ndef test_illegal_transition_is_refused_logged_and_does_not_move():\n    o = new_order()\n    with pytest.raises(IllegalTransition) as e:\n        o.fire("ship")\n    assert o.state == "draft" and "allowed: add_item, submit, cancel" in e.value.reason\n    assert o.history[-1] == {"from": "draft", "event": "ship", "payload": {}, "to": "draft", "ok": False, "reason": e.value.reason}\n\n\ndef test_final_state_refuses_everything():\n    o = new_order()\n    o.fire("cancel")\n    with pytest.raises(IllegalTransition, match="final"):\n        o.fire("add_item")\n    assert o.available() == []\n\n\ndef test_guards_block_until_their_condition_holds():\n    o = new_order()\n    with pytest.raises(GuardRejected) as e:\n        o.fire("submit")\n    assert e.value.reason == "guard(s) said no: has_items" and isinstance(e.value, TransitionRefused)\n    add_item(o, "book", 12)\n    o.fire("submit")\n    assert not o.can("pay", {"amount": 11}) and o.can("pay", {"amount": 12})\n    with pytest.raises(GuardRejected):\n        o.fire("pay", {"amount": 11})\n    o.fire("pay", {"amount": 12})\n    with pytest.raises(GuardRejected, match="has_address"):\n        o.fire("ship")\n    assert o.state == "paid" and [h["ok"] for h in o.history].count(False) == 3\n\n\ndef test_first_passing_guard_wins():\n    spec = {"states": ["a", "big", "small"], "initial": "a", "final": [],\n            "transitions": [{"event": "go", "source": "a", "target": "big", "guard": "large"},\n                            {"event": "go", "source": "a", "target": "small"}]}\n    guards = {"large": lambda ctx, p: p.get("n", 0) > 10}\n    assert Machine(spec, guards).fire("go", {"n": 50}) == "big"\n    assert Machine(spec, guards).fire("go", {"n": 1}) == "small"\n\n\n@pytest.mark.parametrize("change, message", [\n    ({"initial": "nowhere"}, "initial state"),\n    ({"final": ["gone"]}, "final state"),\n    ({"states": ["a", "a"]}, "unique"),\n    ({"transitions": [{"event": "e", "source": "draft", "target": "mars"}]}, "undeclared state \'mars\'"),\n    ({"transitions": [{"event": "e", "source": "draft", "target": "paid", "guard": "nope"}]}, "unknown guard"),\n    ({"transitions": [{"event": "e", "source": "delivered", "target": "paid"}]}, "leaves a final state"),\n    ({"transitions": [{"source": "draft", "target": "paid"}]}, "no \'event\'"),\n])\ndef test_bad_specs_are_refused_at_build_time(change, message):\n    with pytest.raises(SpecError, match=message):\n        Machine(dict(ORDER_SPEC, **change), GUARDS)\n',
   }, 'python -m __PKG__')

# ------------------------------------------------------------------------------------------------ event_bus
_t('event_bus', 'Event bus (pub/sub with replay)',
   'In-process publish/subscribe with * and # topic wildcards, ordered delivery (handlers that publish never jump the queue), failing handlers contained, and an append-only JSON-lines log for replay after a restart.',
   'python', ['api'], {
       **COMMON,
       'README.md': '# __NAME__\n\nIn-process publish/subscribe with an append-only log:\n\n- **Topics** are dot-separated (`orders.created`). A subscription pattern may use `*` for exactly one segment\n  (`orders.*`) and `#` for zero or more (`orders.#`, `#`).\n- **Ordered delivery**: events are delivered in the order they were published, to subscribers in the order they\n  subscribed. A handler that publishes from inside a handler does not jump the queue; its event is delivered after\n  the current one has reached everybody.\n- **A failing handler** is recorded in `bus.errors` and does not stop delivery to the others.\n- **Replay**: every event is appended to a JSON-lines log as it is published. A new `Bus` on the same file carries\n  on numbering, and `replay(pattern, handler, since=N)` re-delivers what happened while you were away.\n\n    python -m __PKG__          # a short demo, log in events.log\n    python -m pytest -q\n',
       'pyproject.toml': '[project]\nname = "__PKG__"\nversion = "0.1.0"\nrequires-python = ">=3.10"\n\n[tool.pytest.ini_options]\ntestpaths = ["tests"]\n',
       '__PKG__/__init__.py': '"""__NAME__: in-process pub/sub with wildcards, ordered delivery and replay from a log."""\n',
       '__PKG__/__main__.py': 'from .bus import Bus\n\n\ndef main(log="events.log"):\n    bus = Bus(log)\n    bus.subscribe("orders.*", lambda e: print(f"[orders] #{e.seq} {e.topic} {e.data}"))\n    bus.subscribe("#", lambda e: print(f"[audit]  #{e.seq} {e.topic}"))\n    start = bus.seq\n    bus.publish("orders.created", {"id": 1})\n    bus.publish("orders.paid", {"id": 1, "amount": 12})\n    bus.publish("users.signed_up", {"name": "ada"})\n    print("replaying orders since", start)\n    count = bus.replay("orders.#", lambda e: print("  replay", e.seq, e.topic), since=start)\n    print(count, "replayed; log:", log)\n\n\nmain()\n',
       '__PKG__/bus.py': '"""The bus. The log file is opened, appended and closed on every publish, so nothing holds it open between\nevents and a crash loses at most the event being written."""\nimport json\nimport os\nimport re\nfrom collections import deque\nfrom dataclasses import dataclass, field\n\n_SEGMENT = re.compile(r"^[A-Za-z0-9_-]+$")\n\n\nclass TopicError(ValueError):\n    """A topic or pattern that is not well formed."""\n\n\n@dataclass(frozen=True)\nclass Event:\n    seq: int\n    topic: str\n    data: object = field(default=None)\n\n\ndef check_topic(topic):\n    parts = topic.split(".")\n    if not topic or not all(_SEGMENT.match(p) for p in parts):\n        raise TopicError(f"bad topic {topic!r}: use dot-separated words, no wildcards")\n    return parts\n\n\ndef check_pattern(pattern):\n    parts = pattern.split(".")\n    if not pattern or not all(p in ("*", "#") or _SEGMENT.match(p) for p in parts):\n        raise TopicError(f"bad pattern {pattern!r}")\n    return parts\n\n\ndef matches(pattern, topic):\n    """`*` = exactly one segment, `#` = zero or more."""\n    return _match(check_pattern(pattern), topic.split("."))\n\n\ndef _match(pat, top):\n    if not pat:\n        return not top\n    head, rest = pat[0], pat[1:]\n    if head == "#":\n        return any(_match(rest, top[i:]) for i in range(len(top) + 1))\n    if not top:\n        return False\n    return (head == "*" or head == top[0]) and _match(rest, top[1:])\n\n\ndef read_log(path):\n    """-> list of Event from a JSON-lines log. A torn last line (crash mid-write) is skipped, not fatal."""\n    if not path or not os.path.exists(path):\n        return []\n    out = []\n    with open(path, "r", encoding="utf-8") as f:\n        for line in f:\n            try:\n                rec = json.loads(line)\n            except ValueError:\n                continue\n            out.append(Event(rec["seq"], rec["topic"], rec.get("data")))\n    return out\n\n\nclass Bus:\n    def __init__(self, log_path=None):\n        self.log_path = log_path\n        self._subs = []                # (token, pattern parts, pattern, handler) in subscription order\n        self._next_token = 1\n        self._queue = deque()\n        self._delivering = False\n        self.errors = []               # (event, pattern, exception)\n        past = read_log(log_path)\n        self.seq = past[-1].seq if past else 0\n\n    def subscribe(self, pattern, handler):\n        """-> token for unsubscribe()."""\n        parts = check_pattern(pattern)\n        token = self._next_token\n        self._next_token += 1\n        self._subs.append((token, parts, pattern, handler))\n        return token\n\n    def unsubscribe(self, token):\n        """-> True if something was removed."""\n        before = len(self._subs)\n        self._subs = [s for s in self._subs if s[0] != token]\n        return len(self._subs) < before\n\n    def publish(self, topic, data=None):\n        """-> the event. Logged first, then delivered (after any event already being delivered)."""\n        check_topic(topic)\n        self.seq += 1\n        event = Event(self.seq, topic, data)\n        if self.log_path:\n            with open(self.log_path, "a", encoding="utf-8") as f:\n                f.write(json.dumps({"seq": event.seq, "topic": topic, "data": data}) + "\\n")\n        self._queue.append(event)\n        if not self._delivering:\n            self._drain()\n        return event\n\n    def _drain(self):\n        self._delivering = True\n        try:\n            while self._queue:\n                event = self._queue.popleft()\n                self._deliver(event, list(self._subs))\n        finally:\n            self._delivering = False\n\n    def _deliver(self, event, subs):\n        top = event.topic.split(".")\n        for _, parts, pattern, handler in subs:\n            if _match(parts, top):\n                try:\n                    handler(event)\n                except Exception as e:  # one broken subscriber must not starve the others; it is recorded\n                    self.errors.append((event, pattern, e))\n\n    def replay(self, pattern, handler, since=0):\n        """Deliver logged events with seq > since that match pattern, in order. -> how many were delivered."""\n        parts = check_pattern(pattern)\n        events = [e for e in read_log(self.log_path) if e.seq > since and _match(parts, e.topic.split("."))]\n        for e in events:\n            handler(e)\n        return len(events)\n',
       'tests/test_bus.py': 'import os\nimport sys\n\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n\nimport pytest  # noqa: E402\n\nfrom __PKG__.bus import Bus, TopicError, matches  # noqa: E402\n\n\ndef collect(bus, pattern):\n    got = []\n    bus.subscribe(pattern, lambda e: got.append((e.seq, e.topic, e.data)))\n    return got\n\n\n@pytest.mark.parametrize("pattern, topic, expected", [\n    ("orders.created", "orders.created", True),\n    ("orders.*", "orders.created", True),\n    ("orders.*", "orders.created.eu", False),\n    ("orders.*", "orders", False),\n    ("orders.#", "orders", True),\n    ("orders.#", "orders.created.eu", True),\n    ("#", "anything.at.all", True),\n    ("*.created", "users.created", True),\n    ("*.created", "users.deleted", False),\n    ("a.#.z", "a.z", True),\n    ("a.#.z", "a.b.c.z", True),\n    ("a.#.z", "a.b.c", False),\n])\ndef test_wildcards(pattern, topic, expected):\n    assert matches(pattern, topic) is expected\n\n\ndef test_subscribe_publish_unsubscribe():\n    bus = Bus()\n    got = collect(bus, "orders.*")\n    other = collect(bus, "users.*")\n    bus.publish("orders.created", {"id": 1})\n    token = bus.subscribe("orders.*", lambda e: got.append("second"))\n    bus.publish("orders.paid", 5)\n    assert bus.unsubscribe(token) and not bus.unsubscribe(token)\n    bus.publish("orders.shipped")\n    assert got == [(1, "orders.created", {"id": 1}), (2, "orders.paid", 5), "second", (3, "orders.shipped", None)]\n    assert other == []\n\n\ndef test_events_published_by_handlers_keep_global_order():\n    bus = Bus()\n    order = []\n    bus.subscribe("a", lambda e: (order.append("first saw a"), bus.publish("b")))\n    bus.subscribe("#", lambda e: order.append(f"audit {e.topic}"))\n    bus.publish("a")\n    assert order == ["first saw a", "audit a", "audit b"]\n\n\ndef test_a_failing_handler_does_not_stop_the_others():\n    bus = Bus()\n\n    def broken(event):\n        raise RuntimeError("boom")\n    bus.subscribe("x", broken)\n    got = collect(bus, "x")\n    bus.publish("x", 1)\n    assert got == [(1, "x", 1)] and len(bus.errors) == 1 and str(bus.errors[0][2]) == "boom"\n\n\n@pytest.mark.parametrize("bad", ["", "a..b", "a.*", "a.#", "has space"])\ndef test_publishing_a_bad_topic_is_refused(bad):\n    with pytest.raises(TopicError):\n        Bus().publish(bad)\n\n\ndef test_replay_after_restart_continues_numbering(tmp_path):\n    log = str(tmp_path / "events.log")\n    first = Bus(log)\n    first.publish("orders.created", {"id": 1})\n    first.publish("users.joined", {"id": 9})\n    first.publish("orders.paid", {"id": 1})\n\n    second = Bus(log)\n    assert second.seq == 3\n    assert second.publish("orders.shipped").seq == 4\n    seen = []\n    assert second.replay("orders.#", seen.append) == 3\n    assert [(e.seq, e.topic) for e in seen] == [(1, "orders.created"), (3, "orders.paid"), (4, "orders.shipped")]\n    later = []\n    assert second.replay("#", later.append, since=2) == 2 and [e.seq for e in later] == [3, 4]\n\n\ndef test_a_torn_last_line_is_skipped(tmp_path):\n    log = tmp_path / "events.log"\n    bus = Bus(str(log))\n    bus.publish("a", 1)\n    with open(log, "a", encoding="utf-8") as f:\n        f.write(\'{"seq": 2, "topic": "a", "da\')\n    again = Bus(str(log))\n    seen = []\n    assert again.seq == 1 and again.replay("#", seen.append) == 1\n    os.remove(log)\n    assert not log.exists()\n',
   }, 'python -m __PKG__')

