_t('cache_layer', 'Cache layer (TTL + LRU)',
   'A TTL + LRU cache with a size bound, hit/miss/eviction/expiration stats, a memoise decorator, and an injectable clock so every test is exact without sleeping.',
   'python', ['api'], {
       **COMMON,
       'README.md': '# __NAME__\n\nA TTL + LRU cache: entries expire after `ttl` seconds, and when the cache holds `max_size` entries the least\nrecently used one is evicted to make room. It counts hits, misses, evictions and expirations.\n\nThe clock is injected (`clock=` any zero-argument function returning seconds), so tests move time forward by\nhand instead of sleeping, and are exact.\n\n    from __PKG__ import TTLCache, cached\n    cache = TTLCache(max_size=256, ttl=30)\n\n    @cached(cache)\n    def price(sku): ...\n\n    python -m __PKG__        # a short demo with a manual clock\n    python -m pytest -q\n',
       'pyproject.toml': '[project]\nname = "__PKG__"\nversion = "0.1.0"\nrequires-python = ">=3.10"\n\n[tool.pytest.ini_options]\ntestpaths = ["tests"]\n',
       '__PKG__/__init__.py': '"""__NAME__: a TTL + LRU cache with stats and an injectable clock."""\nfrom .cache import ManualClock, TTLCache, cached\n\n__all__ = ["ManualClock", "TTLCache", "cached"]\n',
       '__PKG__/__main__.py': 'from .cache import ManualClock, TTLCache, cached\n\n\ndef main():\n    clock = ManualClock()\n    cache = TTLCache(max_size=2, ttl=10, clock=clock)\n    calls = []\n\n    @cached(cache)\n    def square(n):\n        calls.append(n)\n        return n * n\n\n    square(3)\n    square(3)\n    clock.advance(11)\n    square(3)\n    square(4)\n    square(5)\n    print("computed for:", calls)\n    print("stats:", cache.stats())\n\n\nmain()\n',
       '__PKG__/cache.py': '"""TTL + LRU in one OrderedDict: insertion/access order is recency, each value carries its own expiry time."""\nimport functools\nimport threading\nimport time\nfrom collections import OrderedDict\n\n_MISSING = object()\n\n\nclass ManualClock:\n    """A clock you move by hand. Use it in tests instead of time.sleep()."""\n\n    def __init__(self, start=0.0):\n        self.now = float(start)\n\n    def __call__(self):\n        return self.now\n\n    def advance(self, seconds):\n        if seconds < 0:\n            raise ValueError("time does not go backwards")\n        self.now += seconds\n        return self.now\n\n\nclass TTLCache:\n    def __init__(self, max_size=128, ttl=60.0, clock=time.monotonic):\n        if max_size < 1:\n            raise ValueError("max_size must be at least 1")\n        if ttl <= 0:\n            raise ValueError("ttl must be positive")\n        self.max_size, self.ttl, self.clock = max_size, ttl, clock\n        self._data = OrderedDict()           # key -> (expires_at, value)\n        self._lock = threading.Lock()\n        self.hits = self.misses = self.evictions = self.expirations = 0\n\n    def _live(self, key, now):\n        """-> value or _MISSING; drops the entry if it has expired."""\n        item = self._data.get(key, _MISSING)\n        if item is _MISSING:\n            return _MISSING\n        expires_at, value = item\n        if now >= expires_at:\n            del self._data[key]\n            self.expirations += 1\n            return _MISSING\n        return value\n\n    def get(self, key, default=None):\n        with self._lock:\n            value = self._live(key, self.clock())\n            if value is _MISSING:\n                self.misses += 1\n                return default\n            self._data.move_to_end(key)\n            self.hits += 1\n            return value\n\n    def set(self, key, value, ttl=None):\n        ttl = self.ttl if ttl is None else ttl\n        if ttl <= 0:\n            raise ValueError("ttl must be positive")\n        with self._lock:\n            now = self.clock()\n            if key in self._data:\n                del self._data[key]\n            else:\n                self._purge(now)\n                while len(self._data) >= self.max_size:\n                    self._data.popitem(last=False)\n                    self.evictions += 1\n            self._data[key] = (now + ttl, value)\n\n    def delete(self, key):\n        with self._lock:\n            return self._data.pop(key, _MISSING) is not _MISSING\n\n    def __contains__(self, key):\n        with self._lock:\n            return self._live(key, self.clock()) is not _MISSING\n\n    def __len__(self):\n        with self._lock:\n            self._purge(self.clock())\n            return len(self._data)\n\n    def _purge(self, now):\n        """Expired entries go first, so a full cache of stale data never evicts a live entry."""\n        for key in [k for k, (exp, _) in self._data.items() if now >= exp]:\n            del self._data[key]\n            self.expirations += 1\n\n    def get_or_set(self, key, factory, ttl=None):\n        value = self.get(key, _MISSING)\n        if value is _MISSING:\n            value = factory()\n            self.set(key, value, ttl)\n        return value\n\n    def clear(self):\n        with self._lock:\n            self._data.clear()\n\n    def stats(self):\n        lookups = self.hits + self.misses\n        return {"hits": self.hits, "misses": self.misses, "evictions": self.evictions, "expirations": self.expirations,\n                "size": len(self), "max_size": self.max_size, "hit_rate": round(self.hits / lookups, 4) if lookups else 0.0}\n\n\ndef cached(cache, key=None):\n    """Memoise a function in `cache`. key(*args, **kwargs) builds the cache key (default: the arguments)."""\n    def wrap(fn):\n        @functools.wraps(fn)\n        def inner(*args, **kwargs):\n            k = key(*args, **kwargs) if key else (fn.__qualname__, args, tuple(sorted(kwargs.items())))\n            return cache.get_or_set(k, lambda: fn(*args, **kwargs))\n        inner.cache = cache\n        return inner\n    return wrap\n',
       'tests/test_cache.py': 'import os\nimport sys\n\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n\nimport pytest  # noqa: E402\n\nfrom __PKG__ import ManualClock, TTLCache, cached  # noqa: E402\n\n\ndef make(max_size=3, ttl=10):\n    clock = ManualClock(1000)\n    return TTLCache(max_size=max_size, ttl=ttl, clock=clock), clock\n\n\ndef test_hit_and_miss_are_counted():\n    c, _ = make()\n    assert c.get("a") is None\n    c.set("a", 1)\n    assert c.get("a") == 1 and c.get("a") == 1 and c.get("b", "dflt") == "dflt"\n    s = c.stats()\n    assert (s["hits"], s["misses"], s["size"], s["hit_rate"]) == (2, 2, 1, 0.5)\n\n\ndef test_entry_expires_exactly_at_ttl():\n    c, clock = make(ttl=10)\n    c.set("a", 1)\n    clock.advance(9.5)\n    assert c.get("a") == 1\n    clock.advance(0.5)\n    assert c.get("a") is None and "a" not in c and c.expirations == 1\n\n\ndef test_per_entry_ttl_overrides_default():\n    c, clock = make(ttl=10)\n    c.set("short", 1, ttl=2)\n    c.set("long", 2)\n    clock.advance(5)\n    assert c.get("short") is None and c.get("long") == 2\n\n\ndef test_lru_eviction_respects_recent_use():\n    c, _ = make(max_size=3)\n    for k in "abc":\n        c.set(k, k.upper())\n    c.get("a")                 # a is now the most recent; b is the oldest\n    c.set("d", "D")\n    assert "b" not in c and all(k in c for k in "acd") and c.evictions == 1 and len(c) == 3\n\n\ndef test_overwrite_does_not_evict_and_refreshes_ttl():\n    c, clock = make(max_size=2, ttl=10)\n    c.set("a", 1)\n    c.set("b", 2)\n    clock.advance(8)\n    c.set("a", 10)\n    clock.advance(5)\n    assert c.evictions == 0 and c.get("a") == 10 and c.get("b") is None\n\n\ndef test_expired_entries_make_room_before_live_ones_are_evicted():\n    c, clock = make(max_size=2, ttl=10)\n    c.set("old", 1, ttl=1)\n    c.set("live", 2)\n    clock.advance(2)\n    c.set("new", 3)\n    assert c.evictions == 0 and c.expirations == 1 and c.get("live") == 2 and c.get("new") == 3\n\n\ndef test_cached_decorator_calls_once_per_key_until_expiry():\n    c, clock = make(ttl=10)\n    calls = []\n\n    @cached(c)\n    def square(n):\n        calls.append(n)\n        return n * n\n\n    assert [square(3), square(3), square(4)] == [9, 9, 16] and calls == [3, 4]\n    clock.advance(10)\n    assert square(3) == 9 and calls == [3, 4, 3] and square.cache is c\n\n\ndef test_delete_clear_and_bad_settings():\n    c, _ = make()\n    c.set("a", 1)\n    assert c.delete("a") and not c.delete("a")\n    c.set("b", 2)\n    c.clear()\n    assert len(c) == 0\n    with pytest.raises(ValueError):\n        TTLCache(max_size=0)\n    with pytest.raises(ValueError):\n        TTLCache(ttl=0)\n    with pytest.raises(ValueError):\n        c.set("x", 1, ttl=-1)\n    with pytest.raises(ValueError):\n        ManualClock().advance(-1)\n',
   }, 'python -m __PKG__')

