_t('plugin_host', 'Plugin host (discover, validate, isolate)',
   'Discovers plugins in a folder, loads each as its own module, validates a declared interface (NAME, VERSION, API_VERSION, run(payload)), and refuses a plugin that fails to import or validate -- with the reason -- without taking the host down. Runtime faults come back as error results.',
   'python / importlib', ['api'], {
       **COMMON,
       'README.md': '# __NAME__\n\nA plugin host. Every `*.py` file in `plugins/` (names starting with `_` are skipped) is loaded on its own, as a\nseparate module that is never left in `sys.modules`, and checked against the declared interface:\n\n| name | rule |\n|------|------|\n| `NAME` | a string: letters, digits, `_` or `-`, unique across plugins |\n| `VERSION` | a string like `1.2.0` |\n| `API_VERSION` | must equal the host\'s `API_VERSION` (currently 1) |\n| `run(payload)` | a function taking exactly one argument (a dict) and returning a dict |\n\nA plugin that fails to import, raises (or calls `sys.exit`) while loading, or breaks a rule is **refused** with a\nreason, and the host carries on with the rest. A plugin whose `run` raises or returns the wrong type at call time\ngets an error result back instead of taking the host down.\n\n    python -m __PKG__ plugins \'{"text": "hello"}\'\n    python -m pytest -q\n',
       'pyproject.toml': '[project]\nname = "__PKG__"\nversion = "0.1.0"\nrequires-python = ">=3.10"\n\n[tool.pytest.ini_options]\ntestpaths = ["tests"]\n',
       '__PKG__/__init__.py': '"""__NAME__: discover, validate and run plugins without letting a bad one take the host down."""\n',
       '__PKG__/__main__.py': 'import json\nimport sys\n\nfrom .host import Host\n\n\ndef main(argv=None):\n    argv = sys.argv[1:] if argv is None else argv\n    folder = argv[0] if argv else "plugins"\n    payload = json.loads(argv[1]) if len(argv) > 1 else {"text": "hello plugin world"}\n    host = Host(folder)\n    loaded, refused = host.load_all()\n    for r in refused:\n        print(f"refused {r.path}: {r.reason}")\n    for name in loaded:\n        print(name, json.dumps(host.call(name, payload)))\n    return 0 if loaded else 1\n\n\nsys.exit(main())\n',
       '__PKG__/host.py': '"""Discovery, isolated loading, interface validation, and contained calls."""\nimport importlib.util\nimport inspect\nimport os\nimport re\nimport sys\nimport traceback\nfrom dataclasses import dataclass\n\nAPI_VERSION = 1\n_NAME = re.compile(r"^[A-Za-z][A-Za-z0-9_-]{0,63}$")\n_VERSION = re.compile(r"^\\d+\\.\\d+\\.\\d+$")\n\n\n@dataclass(frozen=True)\nclass Plugin:\n    name: str\n    version: str\n    path: str\n    module: object\n\n    def describe(self):\n        return {"name": self.name, "version": self.version, "file": os.path.basename(self.path),\n                "doc": (self.module.__doc__ or "").strip().splitlines()[0] if self.module.__doc__ else ""}\n\n\n@dataclass(frozen=True)\nclass Refusal:\n    path: str\n    reason: str\n\n\ndef discover(folder):\n    """-> sorted list of plugin file paths. A missing folder is simply empty."""\n    if not os.path.isdir(folder):\n        return []\n    return [os.path.join(folder, f) for f in sorted(os.listdir(folder))\n            if f.endswith(".py") and not f.startswith("_") and os.path.isfile(os.path.join(folder, f))]\n\n\ndef validate(module):\n    """-> list of problems with a loaded module (empty = it honours the interface)."""\n    problems = []\n    name = getattr(module, "NAME", None)\n    if not isinstance(name, str) or not _NAME.match(name):\n        problems.append("NAME must be a string of letters, digits, \'_\' or \'-\'")\n    version = getattr(module, "VERSION", None)\n    if not isinstance(version, str) or not _VERSION.match(version):\n        problems.append("VERSION must be a string like \'1.0.0\'")\n    api = getattr(module, "API_VERSION", None)\n    if api != API_VERSION:\n        problems.append(f"API_VERSION is {api!r}, the host speaks {API_VERSION}")\n    run = getattr(module, "run", None)\n    if not callable(run):\n        problems.append("run(payload) is missing")\n    else:\n        try:\n            params = list(inspect.signature(run).parameters.values())\n        except (TypeError, ValueError):\n            params = None\n        positional = [p for p in params or [] if p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD)]\n        if params is None or len(positional) != 1 or any(p.default is p.empty for p in params[1:]):\n            problems.append("run must take exactly one argument (the payload)")\n    return problems\n\n\ndef load_one(path, prefix="__PKG___plugin_"):\n    """-> (module, None) or (None, reason). The module is executed in its own namespace and removed from\n    sys.modules afterwards, so two plugins never share state through imports of each other."""\n    stem = os.path.splitext(os.path.basename(path))[0]\n    mod_name = prefix + re.sub(r"\\W", "_", stem)\n    spec = importlib.util.spec_from_file_location(mod_name, path)\n    if spec is None or spec.loader is None:\n        return None, "cannot be loaded as a Python module"\n    module = importlib.util.module_from_spec(spec)\n    sys.modules[mod_name] = module\n    try:\n        spec.loader.exec_module(module)\n    except SyntaxError as e:\n        return None, f"syntax error on line {e.lineno}: {e.msg}"\n    except SystemExit as e:\n        return None, f"called sys.exit({e.code!r}) while loading"\n    except Exception as e:  # any import-time failure is the plugin\'s problem, reported, never the host\'s crash\n        return None, f"failed while loading: {type(e).__name__}: {e}"\n    finally:\n        sys.modules.pop(mod_name, None)\n    return module, None\n\n\nclass Host:\n    def __init__(self, folder):\n        self.folder = folder\n        self.plugins = {}       # name -> Plugin\n        self.refused = []       # Refusal\n\n    def load_all(self):\n        """(Re)load everything in the folder. -> (loaded names, refusals)."""\n        self.plugins, self.refused = {}, []\n        for path in discover(self.folder):\n            module, reason = load_one(path)\n            if module is not None:\n                problems = validate(module)\n                if problems:\n                    reason = "; ".join(problems)\n                elif module.NAME in self.plugins:\n                    reason = f"NAME {module.NAME!r} is already used by {os.path.basename(self.plugins[module.NAME].path)}"\n            if reason:\n                self.refused.append(Refusal(path, reason))\n                continue\n            self.plugins[module.NAME] = Plugin(module.NAME, module.VERSION, path, module)\n        return sorted(self.plugins), list(self.refused)\n\n    def call(self, name, payload):\n        """-> {"ok": True, "result": {...}} or {"ok": False, "error": "..."}. Never raises for plugin faults."""\n        plugin = self.plugins.get(name)\n        if plugin is None:\n            return {"ok": False, "error": f"no plugin named {name!r}"}\n        if not isinstance(payload, dict):\n            return {"ok": False, "error": "payload must be a dict"}\n        try:\n            result = plugin.module.run(dict(payload))\n        except Exception as e:  # contained: the caller gets the error, the host keeps running\n            tail = traceback.format_exception_only(type(e), e)[-1].strip()\n            return {"ok": False, "error": f"{name} raised {tail}"}\n        if not isinstance(result, dict):\n            return {"ok": False, "error": f"{name} returned {type(result).__name__}, expected dict"}\n        return {"ok": True, "result": result}\n',
       'plugins/upper.py': '"""Upper-cases the payload\'s text."""\nNAME = "upper"\nVERSION = "1.0.0"\nAPI_VERSION = 1\n\n\ndef run(payload):\n    return {"text": str(payload.get("text", "")).upper()}\n',
       'plugins/word_count.py': '"""Counts the words in the payload\'s text."""\nNAME = "word_count"\nVERSION = "1.0.0"\nAPI_VERSION = 1\n\n\ndef run(payload):\n    words = str(payload.get("text", "")).split()\n    return {"words": len(words), "unique": len({w.lower() for w in words})}\n',
       'tests/test_host.py': 'import os\nimport sys\nimport textwrap\n\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n\nfrom __PKG__.host import API_VERSION, Host, discover, load_one, validate  # noqa: E402\n\nGOOD = \'\'\'\n"""Reverses text."""\nNAME = "{name}"\nVERSION = "1.0.0"\nAPI_VERSION = 1\n\n\ndef run(payload):\n    return {{"text": payload["text"][::-1]}}\n\'\'\'\n\n\ndef plugin(folder, filename, source):\n    folder.mkdir(exist_ok=True)\n    (folder / filename).write_text(textwrap.dedent(source), encoding="utf-8")\n\n\ndef refusals(host):\n    return {os.path.basename(r.path): r.reason for r in host.refused}\n\n\ndef test_good_plugin_loads_and_runs(tmp_path):\n    d = tmp_path / "plugins"\n    plugin(d, "rev.py", GOOD.format(name="rev"))\n    host = Host(str(d))\n    loaded, refused = host.load_all()\n    assert loaded == ["rev"] and refused == []\n    assert host.call("rev", {"text": "abc"}) == {"ok": True, "result": {"text": "cba"}}\n    assert host.plugins["rev"].describe()["doc"] == "Reverses text."\n\n\ndef test_broken_plugins_are_refused_with_reasons_and_the_rest_still_load(tmp_path):\n    d = tmp_path / "plugins"\n    plugin(d, "a_good.py", GOOD.format(name="good"))\n    plugin(d, "syntax.py", "def run(payload)\\n    return {}\\n")\n    plugin(d, "boom.py", "raise RuntimeError(\'cannot start\')\\n")\n    plugin(d, "quitter.py", "import sys\\nsys.exit(3)\\n")\n    plugin(d, "no_run.py", "NAME = \'norun\'\\nVERSION = \'1.0.0\'\\nAPI_VERSION = 1\\n")\n    plugin(d, "bad_meta.py", "NAME = 42\\nVERSION = \'one\'\\nAPI_VERSION = 99\\ndef run(payload):\\n    return {}\\n")\n    plugin(d, "two_args.py", "NAME = \'two\'\\nVERSION = \'1.0.0\'\\nAPI_VERSION = 1\\ndef run(a, b):\\n    return {}\\n")\n    plugin(d, "z_dupe.py", GOOD.format(name="good"))\n    plugin(d, "_private.py", "raise RuntimeError(\'must never be imported\')\\n")\n    host = Host(str(d))\n    loaded, _ = host.load_all()\n    r = refusals(host)\n    assert loaded == ["good"]\n    assert set(r) == {"syntax.py", "boom.py", "quitter.py", "no_run.py", "bad_meta.py", "two_args.py", "z_dupe.py"}\n    assert r["syntax.py"].startswith("syntax error on line 1")\n    assert r["boom.py"] == "failed while loading: RuntimeError: cannot start"\n    assert r["quitter.py"] == "called sys.exit(3) while loading"\n    assert r["no_run.py"] == "run(payload) is missing"\n    assert "NAME must be" in r["bad_meta.py"] and "VERSION must be" in r["bad_meta.py"] and "API_VERSION is 99" in r["bad_meta.py"]\n    assert r["two_args.py"] == "run must take exactly one argument (the payload)"\n    assert "already used by a_good.py" in r["z_dupe.py"]\n\n\ndef test_runtime_faults_are_contained(tmp_path):\n    d = tmp_path / "plugins"\n    plugin(d, "crash.py", "NAME = \'crash\'\\nVERSION = \'1.0.0\'\\nAPI_VERSION = 1\\ndef run(payload):\\n    return 1 / 0\\n")\n    plugin(d, "wrong.py", "NAME = \'wrong\'\\nVERSION = \'1.0.0\'\\nAPI_VERSION = 1\\ndef run(payload):\\n    return \'text\'\\n")\n    plugin(d, "rev.py", GOOD.format(name="rev"))\n    host = Host(str(d))\n    host.load_all()\n    assert host.call("crash", {}) == {"ok": False, "error": "crash raised ZeroDivisionError: division by zero"}\n    assert host.call("wrong", {}) == {"ok": False, "error": "wrong returned str, expected dict"}\n    assert host.call("ghost", {})["error"] == "no plugin named \'ghost\'"\n    assert host.call("rev", ["not", "a", "dict"])["error"] == "payload must be a dict"\n    assert host.call("rev", {"text": "ok"})["ok"]\n\n\ndef test_plugins_do_not_leak_into_sys_modules_or_each_other(tmp_path):\n    d = tmp_path / "plugins"\n    plugin(d, "one.py", "COUNTER = []\\n" + GOOD.format(name="one"))\n    plugin(d, "two.py", "COUNTER = []\\n" + GOOD.format(name="two"))\n    host = Host(str(d))\n    host.load_all()\n    host.plugins["one"].module.COUNTER.append(1)\n    assert host.plugins["two"].module.COUNTER == []\n    assert not [m for m in sys.modules if "_plugin_one" in m or "_plugin_two" in m]\n\n\ndef test_reload_picks_up_a_fixed_plugin(tmp_path):\n    d = tmp_path / "plugins"\n    plugin(d, "later.py", "raise ImportError(\'missing dependency\')\\n")\n    host = Host(str(d))\n    assert host.load_all()[0] == []\n    plugin(d, "later.py", GOOD.format(name="later"))\n    assert host.load_all() == (["later"], [])\n\n\ndef test_discover_and_helpers(tmp_path):\n    assert discover(str(tmp_path / "nowhere")) == []\n    plugin(tmp_path, "x.py", GOOD.format(name="x"))\n    (tmp_path / "notes.txt").write_text("not a plugin", encoding="utf-8")\n    assert [os.path.basename(p) for p in discover(str(tmp_path))] == ["x.py"]\n    module, reason = load_one(str(tmp_path / "x.py"))\n    assert reason is None and validate(module) == [] and module.API_VERSION == API_VERSION\n\n\ndef test_shipped_example_plugins_are_valid():\n    folder = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "plugins")\n    host = Host(folder)\n    loaded, refused = host.load_all()\n    assert loaded == ["upper", "word_count"] and refused == []\n    assert host.call("word_count", {"text": "a b A"})["result"] == {"words": 3, "unique": 2}\n',
   }, 'python -m __PKG__ plugins')

