_t('docs_site', 'Documentation site generator',
   'Markdown files in docs/ become a static HTML site with a navigation sidebar, dark mode and a shared stylesheet, through a tiny built-in, HTML-escaping Markdown subset (headings, paragraphs, lists, code blocks, inline code, links). No dependencies.',
   'python / html / css', ['web'], {
       **COMMON,
       'README.md': "# __NAME__\n\nA static documentation generator with no dependencies: every Markdown file in `docs/` becomes an HTML page in\n`site/`, each with the same navigation sidebar (current page marked), a shared stylesheet and dark mode.\n\n    python -m __PKG__              # docs/ -> site/\n    python -m __PKG__ docs out     # choose the folders\n    python -m pytest -q\n\nThe converter in `__PKG__/markdown.py` supports a deliberate subset: `#` to `######` headings, paragraphs,\n`-`/`*` and `1.` lists, fenced code blocks, `inline code`, **bold**, *emphasis* and `[links](page.md)`.\nLinks to `.md` files are rewritten to `.html`; `javascript:` links are refused. Everything else is escaped, so raw\nHTML in a page shows as text instead of running.\n\nPage order in the sidebar: `index.md` first, then the rest by file name. A page's title is its first `#` heading.\n",
       'pyproject.toml': '[project]\nname = "__PKG__"\nversion = "0.1.0"\nrequires-python = ">=3.10"\n\n[tool.pytest.ini_options]\ntestpaths = ["tests"]\n',
       '__PKG__/__init__.py': '"""__NAME__: Markdown in docs/ -> a static HTML site with a navigation sidebar."""\n',
       '__PKG__/__main__.py': 'import sys\n\nfrom .build import build\n\n\ndef main(argv=None):\n    argv = sys.argv[1:] if argv is None else argv\n    src = argv[0] if argv else "docs"\n    out = argv[1] if len(argv) > 1 else "site"\n    try:\n        written = build(src, out)\n    except (OSError, ValueError) as e:\n        print(f"error: {e}", file=sys.stderr)\n        return 1\n    print(f"wrote {len(written)} files to {out}/: {\', \'.join(written)}")\n    return 0\n\n\nsys.exit(main())\n',
       '__PKG__/build.py': '"""docs/*.md -> site/*.html with one shared sidebar. Pure functions plus one build() that writes files."""\nimport html\nimport os\n\nfrom .markdown import to_html\n\nCSS = """:root { --bg: #ffffff; --fg: #1f2328; --muted: #57606a; --accent: #0969da; --side: #f6f8fa; --code: #eff1f3; }\n@media (prefers-color-scheme: dark) {\n  :root { --bg: #0d1117; --fg: #e6edf3; --muted: #9da7b3; --accent: #4493f8; --side: #161b22; --code: #1f2630; }\n}\n* { box-sizing: border-box; }\nbody { margin: 0; display: flex; min-height: 100vh; background: var(--bg); color: var(--fg);\n       font: 16px/1.6 system-ui, -apple-system, "Segoe UI", sans-serif; }\nnav { width: 16rem; flex-shrink: 0; padding: 1.5rem 1rem; background: var(--side); }\nnav p { margin: 0 0 1rem; font-weight: 700; }\nnav ul { list-style: none; margin: 0; padding: 0; }\nnav a { display: block; padding: .3rem .5rem; border-radius: 6px; color: var(--fg); text-decoration: none; }\nnav a:hover, nav a:focus-visible { background: var(--code); }\nnav a[aria-current="page"] { color: var(--accent); font-weight: 600; }\nmain { flex: 1; max-width: 48rem; padding: 2rem 2.5rem; }\na { color: var(--accent); }\ncode { background: var(--code); padding: .1rem .3rem; border-radius: 4px; }\npre { background: var(--code); padding: 1rem; overflow-x: auto; border-radius: 6px; }\npre code { padding: 0; }\n@media (max-width: 40rem) { body { flex-direction: column; } nav { width: auto; } main { padding: 1.5rem 1rem; } }\n"""\n\n\ndef collect(src):\n    """-> [(name, title, html body)] in sidebar order: index first, then by file name."""\n    names = sorted((f for f in os.listdir(src) if f.lower().endswith(".md")), key=lambda f: (f.lower() != "index.md", f.lower()))\n    pages = []\n    for f in names:\n        with open(os.path.join(src, f), "r", encoding="utf-8") as fh:\n            body, headings = to_html(fh.read())\n        name = os.path.splitext(f)[0]\n        title = next((text for level, text, _ in headings if level == 1), name.replace("-", " ").replace("_", " ").title())\n        pages.append((name, title, body))\n    return pages\n\n\ndef nav(pages, current):\n    items = []\n    for name, title, _ in pages:\n        mark = \' aria-current="page"\' if name == current else ""\n        items.append(f\'<li><a href="{html.escape(name)}.html"{mark}>{html.escape(title)}</a></li>\')\n    return "<ul>" + "".join(items) + "</ul>"\n\n\ndef page(site_title, pages, name, title, body):\n    return (\n        "<!doctype html>\\n"\n        \'<html lang="en">\\n<head>\\n<meta charset="utf-8">\\n\'\n        \'<meta name="viewport" content="width=device-width, initial-scale=1">\\n\'\n        f"<title>{html.escape(title)} - {html.escape(site_title)}</title>\\n"\n        \'<link rel="stylesheet" href="style.css">\\n</head>\\n<body>\\n\'\n        f\'<nav aria-label="Documentation">\\n<p>{html.escape(site_title)}</p>\\n{nav(pages, name)}\\n</nav>\\n\'\n        f"<main>\\n{body}\\n</main>\\n</body>\\n</html>\\n"\n    )\n\n\ndef build(src="docs", out="site", site_title="__NAME__"):\n    """-> list of written file names (pages and the stylesheet)."""\n    if not os.path.isdir(src):\n        raise FileNotFoundError(f"no docs folder at {src}")\n    pages = collect(src)\n    if not pages:\n        raise ValueError(f"{src} has no .md files")\n    os.makedirs(out, exist_ok=True)\n    written = []\n    for name, title, body in pages:\n        with open(os.path.join(out, name + ".html"), "w", encoding="utf-8", newline="\\n") as fh:\n            fh.write(page(site_title, pages, name, title, body))\n        written.append(name + ".html")\n    with open(os.path.join(out, "style.css"), "w", encoding="utf-8", newline="\\n") as fh:\n        fh.write(CSS)\n    return written + ["style.css"]\n',
       '__PKG__/markdown.py': '"""A small, safe Markdown subset -> HTML. Block level: headings, paragraphs, lists, fenced code. Inline: code,\nlinks, bold, emphasis. All text is HTML-escaped first, so nothing in a page can inject markup."""\nimport html\nimport re\n\n_HEADING = re.compile(r"^(#{1,6})\\s+(.*?)\\s*#*\\s*$")\n_UL = re.compile(r"^\\s*[-*]\\s+(.*)$")\n_OL = re.compile(r"^\\s*\\d+[.)]\\s+(.*)$")\n_FENCE = re.compile(r"^```\\s*([\\w+-]*)\\s*$")\n_LINK = re.compile(r"\\[([^\\]]+)\\]\\(([^)\\s]+)\\)")\n_SAFE_URL = re.compile(r"^(https?://|mailto:|#|[\\w./-])", re.I)\n\n\ndef slug(text):\n    s = re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")\n    return s or "section"\n\n\ndef rewrite_href(url):\n    """page.md -> page.html (keeping any #anchor); refuse javascript: and other unknown schemes."""\n    if re.match(r"^\\s*(javascript|data|vbscript):", url, re.I) or not _SAFE_URL.match(url):\n        return None\n    if not re.match(r"^[a-z]+:", url, re.I):\n        url = re.sub(r"\\.md(?=$|#)", ".html", url)\n    return url\n\n\ndef inline(text):\n    """Escape, then apply inline rules. Code spans are protected from the other rules."""\n    codes = []\n\n    def keep_code(m):\n        codes.append("<code>" + html.escape(m.group(1)) + "</code>")\n        return f"\\x00{len(codes) - 1}\\x00"\n    text = re.sub(r"`([^`]+)`", keep_code, text)\n    text = html.escape(text, quote=False)\n\n    def link(m):\n        href = rewrite_href(html.unescape(m.group(2)))\n        if href is None:\n            return m.group(1)\n        return f\'<a href="{html.escape(href)}">{m.group(1)}</a>\'\n    text = _LINK.sub(link, text)\n    text = re.sub(r"\\*\\*(.+?)\\*\\*", r"<strong>\\1</strong>", text)\n    text = re.sub(r"(?<![\\w*])\\*(?!\\s)(.+?)(?<!\\s)\\*(?![\\w*])", r"<em>\\1</em>", text)\n    return re.sub(r"\\x00(\\d+)\\x00", lambda m: codes[int(m.group(1))], text)\n\n\ndef to_html(source):\n    """-> (html, headings) where headings is [(level, text, id)] for building a table of contents."""\n    lines = source.replace("\\r\\n", "\\n").split("\\n")\n    out, headings, para, used_ids = [], [], [], {}\n    i = 0\n\n    def flush():\n        if para:\n            out.append("<p>" + inline(" ".join(s.strip() for s in para)) + "</p>")\n            para.clear()\n\n    while i < len(lines):\n        line = lines[i]\n        fence = _FENCE.match(line)\n        if fence:\n            flush()\n            lang = fence.group(1)\n            body = []\n            i += 1\n            while i < len(lines) and not lines[i].startswith("```"):\n                body.append(lines[i])\n                i += 1\n            cls = f\' class="language-{lang}"\' if lang else ""\n            out.append(f"<pre><code{cls}>" + html.escape("\\n".join(body)) + "</code></pre>")\n            i += 1\n            continue\n        heading = _HEADING.match(line)\n        if heading:\n            flush()\n            level, text = len(heading.group(1)), heading.group(2)\n            base = slug(text)\n            used_ids[base] = used_ids.get(base, 0) + 1\n            hid = base if used_ids[base] == 1 else f"{base}-{used_ids[base]}"\n            headings.append((level, text, hid))\n            out.append(f\'<h{level} id="{hid}">{inline(text)}</h{level}>\')\n            i += 1\n            continue\n        for pattern, tag in ((_UL, "ul"), (_OL, "ol")):\n            if pattern.match(line):\n                flush()\n                items = []\n                while i < len(lines) and pattern.match(lines[i]):\n                    items.append("<li>" + inline(pattern.match(lines[i]).group(1)) + "</li>")\n                    i += 1\n                out.append(f"<{tag}>" + "".join(items) + f"</{tag}>")\n                break\n        else:\n            if line.strip():\n                para.append(line)\n            else:\n                flush()\n            i += 1\n    flush()\n    return "\\n".join(out), headings\n',
       'docs/getting-started.md': '# Getting started\n\nBuild the site:\n\n```\npython -m __PKG__ docs site\n```\n\n1. Write a page in `docs/`.\n2. Run the build.\n3. Open `site/index.html` in a browser.\n\nBack to the [home page](index.md).\n',
       'docs/index.md': '# __NAME__\n\nWelcome. This site was generated from the Markdown files in `docs/`.\n\n- Read [Getting started](getting-started.md) first.\n- Then see the [Reference](reference.md).\n',
       'docs/reference.md': '# Reference\n\n## Supported Markdown\n\n- Headings with `#` to `######`\n- Paragraphs, **bold** and *emphasis*\n- Lists, both `-` and `1.`\n- Fenced code blocks\n- Links such as [the home page](index.md)\n\n## Not supported\n\nTables, images and raw HTML. Raw HTML such as <b>this</b> is shown as text.\n',
       'tests/test_build.py': 'import os\nimport sys\nfrom html.parser import HTMLParser\n\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n\nimport pytest  # noqa: E402\n\nfrom __PKG__.build import build  # noqa: E402\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\n\n\nclass Links(HTMLParser):\n    """Collects the sidebar links and checks that every opened tag is closed in order."""\n\n    VOID = {"meta", "link", "br", "hr", "img", "input"}\n\n    def __init__(self):\n        super().__init__()\n        self.nav, self.current, self.stack, self.in_nav, self.title = [], None, [], False, ""\n        self._in_title = False\n\n    def handle_starttag(self, tag, attrs):\n        a = dict(attrs)\n        if tag not in self.VOID:\n            self.stack.append(tag)\n        if tag == "nav":\n            self.in_nav = True\n        if tag == "a" and self.in_nav:\n            self.nav.append(a["href"])\n            if a.get("aria-current") == "page":\n                self.current = a["href"]\n        self._in_title = tag == "title"\n\n    def handle_endtag(self, tag):\n        assert self.stack and self.stack.pop() == tag, f"unbalanced </{tag}>"\n        if tag == "nav":\n            self.in_nav = False\n        self._in_title = False\n\n    def handle_data(self, data):\n        if self._in_title:\n            self.title += data\n\n\ndef parse(path):\n    p = Links()\n    with open(path, "r", encoding="utf-8") as f:\n        p.feed(f.read())\n    p.close()\n    assert p.stack == []\n    return p\n\n\ndef write_docs(folder, pages):\n    folder.mkdir()\n    for name, text in pages.items():\n        (folder / name).write_text(text, encoding="utf-8")\n\n\ndef test_every_page_has_the_same_sidebar_with_itself_marked(tmp_path):\n    src, out = tmp_path / "docs", tmp_path / "site"\n    write_docs(src, {"zeta.md": "# Zeta page\\n\\ntext", "index.md": "# Home\\n\\nSee [zeta](zeta.md).", "alpha.md": "no heading here"})\n    written = build(str(src), str(out), site_title="Demo")\n    assert written == ["index.html", "alpha.html", "zeta.html", "style.css"]\n    for name in ("index", "alpha", "zeta"):\n        p = parse(out / f"{name}.html")\n        assert p.nav == ["index.html", "alpha.html", "zeta.html"] and p.current == f"{name}.html"\n    assert parse(out / "zeta.html").title == "Zeta page - Demo"\n    assert parse(out / "alpha.html").title == "Alpha - Demo"\n\n\ndef test_page_content_is_converted_and_links_point_at_html(tmp_path):\n    src, out = tmp_path / "docs", tmp_path / "site"\n    write_docs(src, {"index.md": "# Home\\n\\n- [Guide](guide.md)\\n\\n```\\n<raw>\\n```\\n", "guide.md": "# Guide\\n"})\n    build(str(src), str(out))\n    text = (out / "index.html").read_text(encoding="utf-8")\n    assert \'<main>\\n<h1 id="home">Home</h1>\' in text\n    assert \'<ul><li><a href="guide.html">Guide</a></li></ul>\' in text\n    assert "<pre><code>&lt;raw&gt;</code></pre>" in text\n    assert text.startswith("<!doctype html>") and \'lang="en"\' in text and \'href="style.css"\' in text\n    assert "prefers-color-scheme: dark" in (out / "style.css").read_text(encoding="utf-8")\n\n\ndef test_missing_or_empty_docs_folder_is_an_error(tmp_path):\n    with pytest.raises(FileNotFoundError):\n        build(str(tmp_path / "nope"), str(tmp_path / "site"))\n    (tmp_path / "empty").mkdir()\n    with pytest.raises(ValueError):\n        build(str(tmp_path / "empty"), str(tmp_path / "site"))\n\n\ndef test_the_shipped_docs_build(tmp_path):\n    written = build(os.path.join(ROOT, "docs"), str(tmp_path / "site"))\n    assert written[0] == "index.html" and "getting-started.html" in written and "reference.html" in written\n    p = parse(tmp_path / "site" / "getting-started.html")\n    assert p.current == "getting-started.html" and p.title.startswith("Getting started - ")\n',
       'tests/test_markdown.py': 'import os\nimport sys\n\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n\nfrom __PKG__.markdown import inline, rewrite_href, to_html  # noqa: E402\n\n\ndef body(md):\n    return to_html(md)[0]\n\n\ndef test_headings_get_ids_and_are_collected():\n    out, heads = to_html("# Title\\n\\n## Part one\\n\\n## Part one\\n")\n    assert \'<h1 id="title">Title</h1>\' in out\n    assert \'<h2 id="part-one">Part one</h2>\' in out and \'<h2 id="part-one-2">Part one</h2>\' in out\n    assert heads == [(1, "Title", "title"), (2, "Part one", "part-one"), (2, "Part one", "part-one-2")]\n\n\ndef test_paragraphs_join_lines_and_split_on_blank_lines():\n    assert body("one\\ntwo\\n\\nthree") == "<p>one two</p>\\n<p>three</p>"\n\n\ndef test_unordered_and_ordered_lists():\n    assert body("- a\\n* b\\n\\n1. x\\n2. y") == "<ul><li>a</li><li>b</li></ul>\\n<ol><li>x</li><li>y</li></ol>"\n\n\ndef test_list_directly_after_paragraph_closes_it():\n    assert body("Intro:\\n- a\\n- b") == "<p>Intro:</p>\\n<ul><li>a</li><li>b</li></ul>"\n\n\ndef test_fenced_code_is_escaped_and_not_formatted():\n    out = body("```python\\nif a < b and **x**:\\n    print(\'<hi>\')\\n```\\nafter")\n    assert out == (\'<pre><code class="language-python">if a &lt; b and **x**:\\n    print(&#x27;&lt;hi&gt;&#x27;)</code></pre>\\n\'\n                   "<p>after</p>")\n\n\ndef test_inline_code_bold_emphasis_and_links():\n    assert inline("use `a*b*c` **now** and *here*") == "use <code>a*b*c</code> <strong>now</strong> and <em>here</em>"\n    assert inline("see [the guide](guide.md#setup)") == \'see <a href="guide.html#setup">the guide</a>\'\n    assert inline("[site](https://example.org/a.md)") == \'<a href="https://example.org/a.md">site</a>\'\n\n\ndef test_raw_html_is_escaped_and_javascript_links_refused():\n    assert body("<script>alert(1)</script>") == "<p>&lt;script&gt;alert(1)&lt;/script&gt;</p>"\n    assert inline("[click](javascript:void)") == "click"\n    assert rewrite_href("javascript:alert(1)") is None and rewrite_href("notes.md") == "notes.html"\n',
   }, 'python -m __PKG__ docs site')

